// Auto-generated blog post contents from reverse-engineered website
export const BLOG_POSTS_CONTENT: Record<string, string> = {
  "postgres-backups-under-the-hood": "<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">There are three main ways to back up a Postgres database:</p>\n<ol class=\"mb-5 list-outside list-decimal space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Logical backups with <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg_dump</code></li>\n<li class=\"leading-7 sm:leading-[1.75]\">Filesystem backups</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Continuous archiving with WAL</li>\n</ol>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The interesting part is how these approaches differ once the database becomes large.</p>\n<h2 id=\"pgdump-is-basically-instructions-to-rebuild-the-database\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg_dump</code> is basically instructions to rebuild the database</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg_dump</code> takes a consistent snapshot of the database and serializes the schema and rows into a dump.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">A simplified version looks something like:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-sql\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">CREATE</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">TABLE</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">users</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">(</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">)</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">;</span></span>\n<span class=\"sh__line\"></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">INSERT</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">INTO</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">users</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">VALUES</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">(</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">,</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&#039;</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">ada</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&#039;</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">)</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">;</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">INSERT</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">INTO</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">users</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">VALUES</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">(</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">2</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">,</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&#039;</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">lin</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&#039;</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">)</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">;</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">INSERT</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">INTO</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">users</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">VALUES</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">(</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">3</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">,</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&#039;</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">mia</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&#039;</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">)</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">;</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So the dump isn&#x27;t really a copy of the database&#x27;s physical state. It&#x27;s more like a set of instructions for reconstructing it.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">That makes it useful for migrations and relatively small databases, but it becomes expensive at large scale. A multi-terabyte database means reading, serializing, formatting and potentially compressing huge amounts of data while competing with the actual workload for CPU and I/O.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">There is also a less obvious problem with <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg_dump</code>.</p>\n<h3 id=\"the-transaction-horizon-problem\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">The transaction horizon problem</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Postgres uses MVCC, so <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg_dump</code> needs to maintain a consistent view of the database while it runs.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">It does this by holding a transaction snapshot for the duration of the dump.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Every transaction in Postgres gets an XID, and tuples contain information about which transaction created or modified them. Since XIDs are 32-bit, they eventually wrap around. Postgres therefore has to periodically freeze old tuples so those XIDs can safely be reused.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Normally, autovacuum moves this process forward.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">But a long-running snapshot can pin the transaction horizon.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So imagine:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">pg_dump</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">starts</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">transaction</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">snapshot</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">stays</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">open</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">transaction</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">horizon</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">cannot</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">move</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">forward</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">autovacuum</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">can</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&#039;</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">t freeze old tuples past it</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">      │</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">      ▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">billions of new transactions happen</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">      │</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">      ▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">transaction wraparound risk</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\"></span></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">If enough transactions happen while that old snapshot is still open, Postgres can eventually refuse new transactions that require XIDs and move into a protective read-only state.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg_dump</code> isn&#x27;t bad. It&#x27;s just a very different tool from what you want for large-scale scheduled disaster-recovery backups.</p>\n<h2 id=\"filesystem-backups-are-much-faster\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Filesystem backups are much faster</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The obvious alternative is to skip SQL completely and copy the actual files that Postgres stores on disk.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This is substantially faster because you&#x27;re copying the physical representation directly.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">But there&#x27;s a problem.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">If Postgres is running while you&#x27;re copying those files, the database can change halfway through the backup.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">For example:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Backup</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">starts</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">copy</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">page</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">A</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">UPDATE</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">users</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">copy</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">page</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">B</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">└──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">finish</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Now page A might represent the old state while page B represents the new state.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Worse, you could theoretically copy a page while it is being modified and end up with corrupted data.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The traditional solution is to shut Postgres down while copying the filesystem.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Obviously, that isn&#x27;t particularly useful for a production database that is supposed to stay online.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This is where WAL becomes important.</p>\n<h2 id=\"wal-is-the-databases-history\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">WAL is the database&#x27;s history</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Postgres uses a <strong class=\"font-semibold text-foreground\">Write-Ahead Log (WAL)</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Before making changes to the actual data files, Postgres records those changes in the WAL.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So instead of thinking about the database as just:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">database</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">files</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">it&#x27;s more useful to think:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">database</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">files</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">+</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">history</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">of</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">changes</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">That history is continuously written into WAL segments.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The WAL contains information about things like:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">which relation was modified</li>\n<li class=\"leading-7 sm:leading-[1.75]\">which page was modified</li>\n<li class=\"leading-7 sm:leading-[1.75]\">what operation happened</li>\n<li class=\"leading-7 sm:leading-[1.75]\">where the operation exists in the WAL stream</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">That last part is represented using an <strong class=\"font-semibold text-foreground\">LSN — Log Sequence Number</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">You can think of an LSN as a position in the database&#x27;s history.</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">──────────────────────────────────────────────►</span></span>\n<span class=\"sh__line\"></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">        </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">LSN</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">100</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">LSN</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">200</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">LSN</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">300</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">           </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">            </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">            </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">           </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">            </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">            </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">        </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">update</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">        </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">insert</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--keyword\" style=\"color:var(--sh-keyword)\">delete</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">And this gives us a way to precisely describe where a backup starts and ends.</p>\n<h2 id=\"continuous-archiving\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Continuous archiving</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Continuous archiving combines:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Filesystem</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">+</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Continuous</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">archiving</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The WAL can be continuously streamed to external storage while the database keeps serving traffic.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This means the filesystem backup itself doesn&#x27;t need to be perfectly consistent.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This sounds wrong at first.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">But that&#x27;s actually the clever part.</p>\n<h3 id=\"the-smeared-backup\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">The &quot;smeared&quot; backup</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Suppose we&#x27;re copying the database files and an update happens in the middle:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-sql\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">UPDATE</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">users</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">SET</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">email_confirmed</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">=</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--keyword\" style=\"color:var(--sh-keyword)\">true</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WHERE</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">id</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">=</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">314159</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">;</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">There are several things that could happen.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The relevant page might have already been copied.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Or it might not have been copied yet.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Or the page could be copied at exactly the wrong moment and end up corrupted.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So the filesystem backup can essentially be a <strong class=\"font-semibold text-foreground\">smeared version of the database</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">And that&#x27;s okay.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Because we also have the WAL.</p>\n<h2 id=\"full-page-writes\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Full-page writes</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This is where <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">full_page_writes</code> becomes important.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">After a checkpoint, when a page is modified for the first time, Postgres can write the entire page into the WAL.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">A Postgres page is usually 8KB.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So instead of only recording:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&quot;</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">change this part of page 42</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&quot;</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">the WAL can contain:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&quot;</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">here is the complete version of page 42</span><span class=\"sh__token--string\" style=\"color:var(--sh-string)\">&quot;</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">That full-page image gives recovery enough information to reconstruct a page even if the corresponding page in the filesystem backup is inconsistent or corrupted.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The whole mechanism starts making sense when you put it together:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                 </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                 </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">continuous</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                 </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Database</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">───────►</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">S3</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">filesystem</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">copy</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Smeared</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The backup records two important LSNs:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">start_lsn</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">─────────────────────</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">end_lsn</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                             </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">begins</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">finishes</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">During restoration, Postgres replays the WAL from <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">start_lsn</code> through <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">end_lsn</code>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So even if the copied files were inconsistent, WAL replay can bring them to a consistent state.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Importantly, the restored database is effectively consistent at the <strong class=\"font-semibold text-foreground\">end of the backup</strong>, not necessarily at its start.</p>\n<h2 id=\"this-is-what-enables-pitr\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">This is what enables PITR</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Once WAL is continuously archived, something much more useful becomes possible:</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Point-in-Time Recovery (PITR).</strong></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Suppose the latest filesystem backup finished at:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">12</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">00</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">But the database crashed at:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">18</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">37</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">We don&#x27;t need another full filesystem backup from 18:37.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">We can:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Restore</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">base</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Replay</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">12</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">01</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">13</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">00</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">14</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">00</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">├──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">18</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">36</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">└──</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">18</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">37</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">             </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">             </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">       </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Desired</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">database</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">state</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Because the WAL contains the history after the base backup, we can replay it until an arbitrary point in time.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">That&#x27;s PITR.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The tradeoff is that replaying a huge amount of WAL is expensive. So backups need to happen frequently enough that a restore doesn&#x27;t require replaying days of WAL.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">PlanetScale&#x27;s setup takes backups every 12 hours by default for this reason.</p>\n<h2 id=\"the-really-interesting-part-backups-and-resizing-use-the-same-machinery\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">The really interesting part: backups and resizing use the same machinery</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The same mechanism can also be used when resizing a Postgres cluster.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The process is roughly:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">New</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">node</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Restore</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">latest</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">filesystem</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Replay</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Catch</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">up</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--keyword\" style=\"color:var(--sh-keyword)\">with</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">primary</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Stream</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">remaining</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">changes</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Cut</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">over</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">And there&#x27;s a nice recursive idea here.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The backup process itself can use a throwaway node:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Latest</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Throwaway</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">node</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Replay</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">until</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">caught</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">up</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Create</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--keyword\" style=\"color:var(--sh-keyword)\">new</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">filesystem</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">backup</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So the primary doesn&#x27;t have to spend all its CPU, I/O and network bandwidth creating the backup.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The same primitives are being reused for backup creation, restoration, replication catch-up and cluster resizing.</p>\n<h2 id=\"the-mental-model\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">The mental model</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The easiest way I think about the whole system is:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-text\"><span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                 </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Continuous</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">              </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">┌──────────────┐</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">              </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Object</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Store</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">              </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">└──────────────┘</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▲</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">WAL</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">replay</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">┌──────────┐</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">┌───────────┐</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Postgres</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│───►│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Base</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">     </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Primary</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Backup</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">└──────────┘</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">   </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">└───────────┘</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">│</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">                      </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">▼</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--space\" style=\"color:var(--sh-space)\">              </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Restored</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">database</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">A base backup gives you a starting point.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">WAL gives you the history after that starting point.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">PITR is basically choosing how far through that history you want to replay.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">So a backup doesn&#x27;t necessarily have to be a perfect snapshot of the database.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">It can be:</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">a physical starting point + enough history to reconstruct the state you need.</strong></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">And that&#x27;s the part that makes Postgres&#x27; backup system much more interesting than just <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg_dump &gt; backup.sql</code>.</p>",
  "it-worked-in-staging-production-destroyed-it-queues-saved-it": "<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">On a random Tuesday in March, I got assigned a task to build a complete feature end to end. The goal was straightforward. When a user uploads an image of a water quality test sample, the system should notify them on WhatsApp and ping the admins or test reviewers. Once a reviewer finishes the analysis, the system generates an AI summary comparing the parameters to global safety standards, compiles a branded PDF report, stores it in cloud storage, and sends the customer a notification with a download link. Finally, if dangerous contaminant levels are detected and a physical device is linked to the test, an emergency support ticket gets raised automatically.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Sounds like a long trip. And it is. A single test completion triggers multiple sequential external API calls. OpenAI alone takes 5 to 10 seconds, and the PDF service adds another 2 to 3 seconds on top. End to end, processing one test can easily consume 15 or more seconds of wall clock time.</p>\n<h2 id=\"what-i-built-first\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">What I Built First</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">With my understanding of the architecture at the time, I went with the most straightforward approach I knew. The pipeline was sequential and synchronous:</p>\n<ol class=\"mb-5 list-outside list-decimal space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Receive the test payload from the database trigger</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Call OpenAI to generate the AI summary</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Generate the PDF report on the server using that summary</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Save the report to BunnyCDN</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Update the database with the CDN URL</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Send out WhatsApp and push notifications</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Evaluate results against safety thresholds and raise emergency tickets if needed</li>\n</ol>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">It worked perfectly on my local machine. I pushed it to staging, ran through the test cases, and everything looked solid. I shipped it.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">A few days later, my manager called. Reports were not generating. I checked locally—everything still worked fine. I assumed it was an environment mismatch, tightened up the config, and pushed again. Same thing happened a few days later, except this time the server actually crashed.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">I opened Grafana to look at the logs and finally saw the real issue. <strong class=\"font-semibold text-foreground\">Postgres was throwing connection limit errors. The whole pipeline was completely synchronous and it was choking the database.</strong></p>\n<h2 id=\"why-the-synchronous-approach-failed\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Why the Synchronous Approach Failed</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The root of the problem was something I had not thought about carefully enough. Our application uses a PostgreSQL <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">LISTEN</code> client to receive database change notifications. This client holds an open database connection for the entire lifetime of its session. The moment a <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">waterquality_changed</code> notification came in, my listener would <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">await</code> the entire pipeline, all 5–10 seconds of it while that database connection stayed open.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Now imagine five testers submitting results at the same time during a field session. That is five listeners each holding a Postgres connection open for 15 seconds simultaneously. Our connection pool has a hard limit. Once it is full, every other part of the application that needs a database connection—API endpoints, cron jobs, other listeners—starts timing out and throwing errors. Unhandled rejections in Node.js are fatal to the process. The server goes down and returns 502 errors to everyone until it restarts.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Even in scenarios that never hit full pool exhaustion, the synchronous approach had zero resilience. If OpenAI was temporarily unavailable or the PDF service timed out halfway through, the entire job would fail silently. There was no retry. The customer would never receive their report or notification, and from the outside the feature looked like it was working because the test data was saved correctly to the database. The downstream processing had just evaporated without a trace.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"queue-problem\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*bDb3uEtp9wivUqvqsubf8w.png\"/></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">What made it worse was that everything had looked fine in staging. Staging has light, predictable traffic. Production has field testers submitting results in bursts. That mismatch is what hid the problem until it blew up in a live environment.</p>\n<h2 id=\"the-architecture-we-already-had\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">The Architecture We Already Had</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Here is the part I wish I had noticed earlier. <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code> was not something we needed to introduce—it was already the backbone of our background processing for sensor data streams, device status events, emergency handling, and more. It is a durable job queue that persists jobs directly to Postgres, manages worker polling, enforces concurrency limits, automates retries with configurable backoff, and routes permanently failed jobs to Dead Letter Queues for human review.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The water quality pipeline had simply never been wired into it. The fix was to route this heavy, fault-prone processing chain through the same infrastructure that was already handling our most critical real-time workloads.</p>\n<h2 id=\"the-fix-separating-the-trigger-from-the-processing\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">The Fix: Separating the Trigger from the Processing</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The core architectural change was clean. Instead of the trigger listener doing all the work, it now does only one thing: receive the database notification and hand the payload off to a background queue immediately. That handoff takes milliseconds. The database connection is released right away, regardless of how long the downstream processing takes.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">On the other side, a new dedicated worker continuously polls the <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">wq-report-pipeline</code> queue for jobs. When it picks one up, it runs the full processing chain—AI summary, PDF generation, notification dispatch, and safety checks—entirely in the background, completely detached from the trigger lifecycle. The worker is configured with a hard concurrency limit of three simultaneous jobs, which prevents a spike of uploads from overwhelming OpenAI or the PDF service at the same time.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Two queues were registered: the main <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">wq-report-pipeline</code> for active jobs, and <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">wq-report-pipeline_dlq</code> as its Dead Letter Queue. The DLQ has to be registered first because <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code> validates the foreign key relationship at creation time. Any job that exhausts its retry limit gets automatically moved to the DLQ, where it can be inspected and manually replayed once the root cause is resolved. No report is permanently lost due to a transient infrastructure failure.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"queue-architecture\" src=\"https://miro.medium.com/v2/resize:fit:1292/format:webp/0*DNhgT3BVZBuCoV3H\"/></p>\n<h2 id=\"the-hidden-bugs-that-came-after\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">The Hidden Bugs That Came After</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Wiring the pipeline into <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code> was not the end of it. Deploying the integration revealed several bugs—some from our own logic, some from breaking changes in <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code> v10 that were not obvious until they hit production.</p>\n<h3 id=\"the-queue-that-never-existed\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">The Queue That Never Existed</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The first symptom was <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">boss.send()</code> consistently returning <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">null</code> as the job ID. In <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code>, a null return from <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">send()</code> means the queue row could not be found in the database during the job insertion. The queue simply did not exist.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The reason was subtle. Our queue setup script initialized over fifteen queues inside a single shared error handler. If any queue earlier in that list encountered a conflict or a foreign key violation during startup, the exception would be caught at the top level and the entire remaining initialization sequence would be abandoned silently. Our <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">wq-report-pipeline</code> queue added in the middle of the list never made it into the database.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The fix was to give every queue its own isolated error handler. One queue failing during startup now produces a single log warning for that specific queue and nothing else. We also added an explicit <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">updateQueue</code> call for <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">wq-report-pipeline</code> on every startup, because <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code> uses <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">ON CONFLICT DO NOTHING</code> in its queue creation SQL. If the queue row already existed from a previous deployment with stale or missing configuration, <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">createQueue</code> would silently skip updating it. The <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">updateQueue</code> call ensures the retry limits, expiry, and dead letter configuration are always in sync with the current code.</p>\n<h3 id=\"pg-boss-v10-breaking-changes\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code> v10 Breaking Changes</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">We had recently upgraded to <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">pg-boss</code> v10 and hit two breaking changes that were not immediately obvious.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">First, <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">deadLetter</code> can no longer be passed inside the <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">send()</code> options. In older versions this was tolerated. In v10 it is strictly a queue-level policy. Passing it in <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">send()</code> caused the internal job insertion to fail silently which is exactly why <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">send()</code> kept returning <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">null</code> even after the queue initialization issue was fixed.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Second, the worker handler signature changed. In earlier versions, the <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">.work()</code> callback received a single job object as its argument. In v10 it receives an array of jobs, even when only one job is being processed at a time. Our worker was trying to read properties like <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">id</code> and <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">data</code> directly off an array, which returned <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">undefined</code>. The logs showed <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Starting wq-report-pipeline job undefined</code> followed immediately by a crash reading <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">device_id</code> from an undefined value. Updating the handler to iterate over the received array fixed this completely.</p>\n<h2 id=\"before-vs-after\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Before vs. After</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"before-after\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*ypr2Ka2KfKozw1CF-udBpA.png\"/></p>\n<h2 id=\"why-this-actually-holds-under-load\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Why This Actually Holds Under Load</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"under-load\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*4amM-v67KDzFi4MynXW9Yg.png\"/></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Ten simultaneous uploads now result in ten near-instant trigger handoffs. The database connection pool is never pressured by the processing pipeline. Jobs wait safely in Postgres, durable across server restarts, and are processed in a controlled, throttled manner. Transient failures at any external service result in an automatic retry, not silent data loss. The main API thread is never blocked.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The honest takeaway for me was that the synchronous approach did not feel wrong when I was building it. It worked locally. It worked in staging. It only betrayed me when real, concurrent load hit it in production. That gap between “works on my machine” and “works under pressure” is exactly what asynchronous job queues are designed to close.</p>",
  "horizontal-scaling-in-databases-part-1-read-replicas": "<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">As applications grow, databases are often the first thing to feel the pressure because systems ask a lot from them. Thousands of users reading data, refreshing pages, loading feeds all at the same time.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">One important observation drives the design shown in this diagram:</p>\n<blockquote class=\"my-6 border-l-2 border-border pl-5 text-[15px] italic leading-7 text-muted-foreground sm:text-base\">\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\"><em class=\"italic\">Most applications have the read to write ratio very huge.</em></strong></p>\n</blockquote>\n<h2 id=\"the-core-problem-one-database-too-much-load\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">The Core Problem: One Database, Too Much Load</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">If a single database handles everything from reads and writes, it eventually becomes a bottleneck. Even if writes are limited, heavy read traffic can slow down the system, increase latency, and affect write performance.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">At scale, the goal is not just to store data correctly, but to <strong class=\"font-semibold text-foreground\">serve it efficiently</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Replication is the strategy that allows this.</p>\n<h2 id=\"separating-responsibilities\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Separating Responsibilities</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">A replicated database system typically assigns different responsibilities to different nodes.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">One database acts as the <strong class=\"font-semibold text-foreground\">primary source of truth</strong>. It is responsible for accepting all write operations. Any change to data inserts, updates, deletes happens here first.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Other databases act as <strong class=\"font-semibold text-foreground\">replicas</strong>. <strong class=\"font-semibold text-foreground\">Their job is not to modify data, but to serve read requests</strong>. They maintain copies of the primary’s data and respond to queries that only need to fetch information.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This separation alone dramatically improves performance, because read-heavy traffic no longer competes with writes.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Separating Responsibilities\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*7Qfm38lm8vwGVCB7AIazAQ.png\"/></p>\n<h2 id=\"keeping-data-in-sync\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Keeping Data in Sync</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Once multiple databases exist, the obvious question arises: <strong class=\"font-semibold text-foreground\">how do they stay consistent?</strong></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">That’s where replication strategies come in.</p>\n<h2 id=\"synchronous-replication\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Synchronous Replication</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">In synchronous replication, when a write occurs, the system ensures that <strong class=\"font-semibold text-foreground\">both the primary database and its replica record the change before confirming success.</strong></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This approach guarantees strong consistency. Every database reflects the same state at all times.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The tradeoff is <strong class=\"font-semibold text-foreground\">speed</strong>. <strong class=\"font-semibold text-foreground\">Writes take longer</strong> because the system waits for confirmation from replicas. If a replica is slow or unavailable, write operations can be delayed.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This model is chosen when correctness is non-negotiable — situations where even a brief inconsistency would be unacceptable.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Synchronous Replication\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*06fbG2w2chjaUtSXPD1qcQ.png\"/></p>\n<h2 id=\"asynchronous-replication\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Asynchronous Replication</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Asynchronous replication takes a different approach.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Here, <strong class=\"font-semibold text-foreground\">the primary database commits the write and immediately responds. Replicas update themselves afterward, often by periodically pulling new changes from the primary.</strong></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This makes the system much faster and more resilient under load. Writes are quick, and the system remains responsive even during traffic spikes.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">The tradeoff is that replicas may briefly lag behind</strong>. For a short window, a read might return slightly outdated data.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">In practice, this delay is acceptable for most applications, which is why asynchronous replication dominates real-world systems.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Asynchronous Replication\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*2oOAQGJd6v8CqIQP9_mroQ.png\"/></p>\n<h2 id=\"why-this-tradeoff-is-worth-it\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Why This Tradeoff Is Worth It</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Modern systems are built around user experience. Speed matters more than perfect freshness in most scenarios.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">A user scrolling a feed or viewing a product list does not notice a few milliseconds of delay in data synchronization, but they do notice slow page loads and laggy interactions.</p>",
  "move-your-medium-articles-to-your-own-platform-in-less-than-1-minute": "<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"mdify Banner\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*aLw_PNB6Q27U2j96KkTWjw.png\"/></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Are you a blogger or developer who wants to convert your Medium articles into clean, editable Markdown format quickly?</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Markdown is a popular plain text format widely used for writing on platforms like GitHub, dev.to, and static site generators. Thankfully, there is a handy web tool called <a target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-foreground underline underline-offset-2 decoration-neutral-400 dark:decoration-neutral-600 hover:decoration-foreground transition-colors\" href=\"https://mdify.vedantworks.com/\"><strong class=\"font-semibold text-foreground\">mdify</strong></a> that makes this conversion effortless with just a single click.</p>\n<h2 id=\"what-is-mdify\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">What is mdify?</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">mdify is a web application designed to convert Medium articles into Markdown text. You simply paste the URL of the Medium article you want to convert, and the tool fetches the content, cleans it up, and provides you with editable Markdown output instantly. <strong class=\"font-semibold text-foreground\"><em class=\"italic\">There’s no need for complicated installations or coding—everything happens right in your browser.</em></strong></p>\n<h2 id=\"why-convert-medium-articles-to-markdown\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Why Convert Medium Articles to Markdown?</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Medium’s native format is HTML-rich and optimized for its platform, but it can be difficult to repurpose your content for other blogs, static websites, or version-controlled repositories. Markdown is:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Easier to edit and maintain</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Compatible with many blogging and documentation platforms</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Lightweight and human-readable</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Perfect for integrating with Git-based workflows</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">By converting your Medium articles to Markdown, you can have more control over how and where you publish your content.</p>\n<h2 id=\"how-to-use-mdify\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">How to Use mdify?</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Using <a target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-foreground underline underline-offset-2 decoration-neutral-400 dark:decoration-neutral-600 hover:decoration-foreground transition-colors\" href=\"https://mdify.vedantworks.com/\">mdify</a> is simple and straightforward:</p>\n<ol class=\"mb-5 list-outside list-decimal space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Copy the URL of the Medium article you want to convert.</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Go to the website: <a target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-foreground underline underline-offset-2 decoration-neutral-400 dark:decoration-neutral-600 hover:decoration-foreground transition-colors\" href=\"https://mdify.vedantworks.com/\"><strong class=\"font-semibold text-foreground\">mdify.vedantworks.com</strong></a></li>\n<li class=\"leading-7 sm:leading-[1.75]\">Paste your Medium URL into the input box on the site.</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Click the convert button or press enter.</li>\n<li class=\"leading-7 sm:leading-[1.75]\">The site will process the article and output clean, formatted Markdown.</li>\n</ol>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Example blog\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*PLQzav5p7wnyk_4HyV7UUw.png\"/></p>\n<ol class=\"mb-5 list-outside list-decimal space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\" start=\"6\">\n<li class=\"leading-7 sm:leading-[1.75]\">Edit the Markdown if needed directly on the site.</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Copy the Markdown text to your clipboard for use in your projects or blogs.</li>\n</ol>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This tool also preserves essential elements like images and links, allowing easy customization after conversion.</p>\n<h2 id=\"benefits-of-using-mdify\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Benefits of Using mdify</h2>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Quick &amp; easy</strong>: No installations or technical setup.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Free to use</strong>: Openly accessible in your browser.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Clean output</strong>: Generates well-formatted Markdown.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Editable interface</strong>: Tweak the output before copying.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Perfect for bloggers/developers</strong>: Streamlines content migration from Medium.</li>\n</ul>\n<h2 id=\"additional-tips\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Additional Tips</h2>\n<blockquote class=\"my-6 border-l-2 border-border pl-5 text-[15px] italic leading-7 text-muted-foreground sm:text-base\">\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">For archiving or migration, download images locally and update paths in Markdown after conversion.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Use Markdown editors or static site generators to preview and publish your content flawlessly.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Combine mdify with version control for content versioning and collaboration.</p>\n</blockquote>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\"><em class=\"italic\">Try it out today and convert your Medium articles seamlessly into Markdown!</em></strong></p>",
  "how-a-14-line-protocol-became-the-god-of-the-web": "<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"HTTP Banner\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/0*6u-mNJ6TX2KYsTRT.png\"/></p>\n<h2 id=\"this-blog-was-converted-from-a-mediumcom-blog-to-mdx-using-the-mdify\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">This blog was converted from a medium.com blog to mdx using the mdify.</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">If you’ve ever wondered how your browser fetches websites or how APIs send and receive data, the answer lies in a powerful, simple protocol: <strong class=\"font-semibold text-foreground\">HTTP (HyperText Transfer Protocol)</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">This blog breaks down <strong class=\"font-semibold text-foreground\">how HTTP works</strong>, from first principles to modern features like caching, CORS, and HTTPS. No fluff. Just what you need to deeply understand the web’s backbone.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Imagine you’re visiting <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">https://example.com</code>. You type the address into your browser, hit Enter, and a webpage appears.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Behind the scenes, your computer is having a structured conversation with another computer (a server). That conversation happens through <strong class=\"font-semibold text-foreground\">HTTP</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Let’s explore how this works from first principles.</p>\n<h2 id=\"what-is-http\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">What is HTTP?</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">HTTP</strong> is a protocol—a set of rules—that defines how clients (like browsers) communicate with servers over the web.</p>\n<h3 id=\"1-why-do-we-need-http\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">1. Why do we need HTTP?</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Problem</strong>: Two computers connected by the Internet can send packets, but they lack a standard <em class=\"italic\">language</em> to request and deliver documents.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">Solution</strong>: Define a <em class=\"italic\">text-based</em> application-layer protocol that:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Identifies what is being requested (a method + a path).</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Describes how to interpret the response (metadata headers).</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Carries the actual content (the body).</li>\n</ul>\n<h3 id=\"2-evolution-of-http\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">2. Evolution Of HTTP</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">HTTP has gone through multiple versions:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">HTTP/0.9</strong> — Basic GET only, no headers.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">HTTP/1.0</strong> — Introduced headers and status codes.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">HTTP/1.1</strong> — Persistent connections, chunked transfer.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">HTTP/2</strong> — Binary format, multiplexed streams, faster.</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">HTTP/3</strong> — Uses QUIC over UDP, built-in encryption.</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Evolution of HTTP\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/0*AS_1tPxHO-s2_6Tn.jpg\"/></p>\n<h3 id=\"3-core-ideas-behind-http\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">3. Core Ideas Behind HTTP</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Core Ideas\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/1*fzL1tgFB52cB2CtXvAfILw.png\"/></p>\n<h2 id=\"4-http-messages-requests-and-responses\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">4. HTTP Messages: Requests and Responses</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">HTTP communication happens through <strong class=\"font-semibold text-foreground\">messages</strong>, which are either requests or responses.</p>\n<h3 id=\"41-a-request-from-client-to-server\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">4.1 A <strong class=\"font-semibold text-foreground\">Request</strong> from client to server</h3>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-http\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">GET</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">index</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--property\" style=\"color:var(--sh-property)\">html</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">HTTP</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Host</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">example</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--property\" style=\"color:var(--sh-property)\">com</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">User</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Agent</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">curl</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">8</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">0</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Accept</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">text</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">html</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<h3 id=\"42-a-response-from-server-to-client\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">4.2 A <strong class=\"font-semibold text-foreground\">Response</strong> from server to client</h3>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-http\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">HTTP</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">200</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">OK</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Content</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Type</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">text</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">html</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">;</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">charset</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">=</span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">utf</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">8</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Content</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Length</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1256</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Date</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Tue</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">,</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">29</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Jul</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">2025</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">08</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">30</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">00</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">GMT</span></span>\n<span class=\"sh__line\"></span>\n<span class=\"sh__line\"><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">&lt;</span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">html</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">&gt;</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1256</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">bytes</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">&lt;/</span><span class=\"sh__token--entity\" style=\"color:var(--sh-entity)\">html</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">&gt;</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<h2 id=\"5-key-http-mechanisms\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">5. Key HTTP Mechanisms</h2>\n<h3 id=\"51-headers-why-and-what\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">5.1 Headers: Why and What</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Headers provide <strong class=\"font-semibold text-foreground\">meta-information</strong>. They define:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">What kind of data is being sent (<code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Content-Type</code>)</li>\n<li class=\"leading-7 sm:leading-[1.75]\">What response formats are acceptable (<code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Accept</code>)</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Authentication (<code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Authorization</code>)</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Language preference, caching instructions, and more.</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Headers are the <strong class=\"font-semibold text-foreground\">control panel</strong> of an HTTP message.</p>\n<h3 id=\"52-methods\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">5.2 Methods</h3>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Each HTTP request includes a <strong class=\"font-semibold text-foreground\">method</strong> to describe what action is being performed:</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Methods\" src=\"https://miro.medium.com/v2/resize:fit:1022/format:webp/1*bzJTOGCddfdnnx0uMxwPaw.png\"/></p>\n<h3 id=\"53-status-codes\" class=\"mt-9 mb-2 scroll-mt-24 text-balance text-lg font-semibold tracking-tight text-foreground\">5.3 Status Codes</h3>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">1xx</code> <strong class=\"font-semibold text-foreground\">Informational</strong> – Continue, Switching Protocols</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">2xx</code> <strong class=\"font-semibold text-foreground\">Success</strong> – 200 OK, 201 Created</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">3xx</code> <strong class=\"font-semibold text-foreground\">Redirection</strong> – 301 Moved Permanently, 307 Temporary Redirect</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">4xx</code> <strong class=\"font-semibold text-foreground\">Client Error</strong> – 400 Bad Request, 404 Not Found</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">5xx</code> <strong class=\"font-semibold text-foreground\">Server Error</strong> – 500 Internal Server Error, 502 Bad Gateway</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"Status Codes\" src=\"https://miro.medium.com/v2/resize:fit:644/format:webp/0*eLHz0brTA7WEKW-h\"/></p>\n<h2 id=\"6-caching-in-http\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">6. Caching in HTTP</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">To avoid downloading the same data over and over, browsers rely on <strong class=\"font-semibold text-foreground\">HTTP caching</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Key headers involved:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Cache-Control</code>: defines caching policy</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">ETag</code>: lets server determine if content changed</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Last-Modified</code>: another way to check freshness</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Smart caching improves speed and reduces server load.</p>\n<h2 id=\"7-options-method-and-the-cors-workflow\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">7. OPTIONS Method and the CORS Workflow</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">OPTIONS</code> method is used by browsers to determine what’s allowed before making certain cross-origin requests. This is known as a <strong class=\"font-semibold text-foreground\">CORS preflight request</strong>.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">It asks the server: <em class=\"italic\">&quot;Can I send a POST request with JSON content from this origin?&quot;</em></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The server must respond with headers like:</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-http\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Access</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Control</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Allow</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Origin</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">https</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--comment\" style=\"color:var(--sh-comment)\">//client.com</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--comment\" style=\"color:var(--sh-comment)\"></span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Access</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Control</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Allow</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Methods</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">POST</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">,</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">GET</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">,</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">OPTIONS</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Access</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Control</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Allow</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Headers</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Content</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">-</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Type</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><img class=\"rounded-xl my-6 w-full border border-neutral-200 dark:border-neutral-800\" alt=\"CORS\" src=\"https://miro.medium.com/v2/resize:fit:1400/format:webp/0*Q8mB1pqJ9-xUXwmH.png\"/></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Without proper CORS headers, browsers will <strong class=\"font-semibold text-foreground\">block</strong> the request even if the server responds.</p>\n<h2 id=\"8-content-negotiation\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">8. Content Negotiation</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">HTTP allows clients to express preferences using headers like:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Accept</code>: preferred content type (<code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">application/json</code>, <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">text/html</code>)</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Accept-Language</code>: preferred languages (<code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">en</code>, <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">fr</code>)</li>\n<li class=\"leading-7 sm:leading-[1.75]\"><code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">Accept-Encoding</code>: compression formats (<code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">gzip</code>, <code class=\"bg-neutral-100 dark:bg-neutral-800 text-neutral-800 dark:text-neutral-200 rounded px-1.5 py-0.5 text-[0.875em] font-mono border border-neutral-200 dark:border-neutral-700\">br</code>)</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The server uses this info to tailor the response.</p>\n<pre class=\"bg-neutral-950 dark:bg-neutral-900 rounded-xl border border-neutral-800 p-5 overflow-x-auto text-sm leading-relaxed my-6 font-mono\"><code class=\"language-http\"><span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">GET</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">doc</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">HTTP</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">.</span><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">1</span></span>\n<span class=\"sh__line\"><span class=\"sh__token--class\" style=\"color:var(--sh-class)\">Accept</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">:</span><span class=\"sh__token--space\" style=\"color:var(--sh-space)\"> </span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">application</span><span class=\"sh__token--sign\" style=\"color:var(--sh-sign)\">/</span><span class=\"sh__token--identifier\" style=\"color:var(--sh-identifier)\">pdf</span></span>\n<span class=\"sh__line\"></span></code></pre>\n<h2 id=\"9-ssl-tls-and-https\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">9. SSL, TLS and HTTPS</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">HTTP alone is insecure — all data is transmitted in plain text.</p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\"><strong class=\"font-semibold text-foreground\">HTTPS = HTTP + TLS (Transport Layer Security)</strong></p>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">TLS encrypts the data, preventing:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Eavesdropping (privacy)</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Tampering (integrity)</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Impersonation (authentication)</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Modern browsers require HTTPS for:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Accessing camera/mic</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Storing cookies securely</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Using advanced APIs (like service workers)</li>\n</ul>\n<h2 id=\"tldr-why-you-should-care\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">TL;DR: Why You Should Care</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Understanding HTTP from the ground up helps you:</p>\n<ul class=\"mb-5 list-outside list-disc space-y-2 pl-5 text-[15px] text-foreground/75 marker:text-muted-foreground sm:text-base\">\n<li class=\"leading-7 sm:leading-[1.75]\">Debug network issues faster</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Build secure and performant APIs</li>\n<li class=\"leading-7 sm:leading-[1.75]\">Master browser behavior (CORS, caching, headers)</li>\n</ul>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">If you build for the web, <strong class=\"font-semibold text-foreground\">you speak HTTP</strong>, whether you know it or not.</p>",
  "demo-blog-2": "<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Next.js has revolutionized how we build web applications. With the release of the App Router and React Server Components, it&#x27;s more powerful than ever.</p>\n<h2 id=\"server-components\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Server Components</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">Server Components allow us to render components on the server, reducing the amount of JavaScript sent to the client. This leads to faster page loads and better SEO.</p>\n<h2 id=\"app-router\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">App Router</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">The file-system based router is intuitive and makes handling layouts, nested routes, and loading states a breeze.</p>\n<h2 id=\"conclusion\" class=\"mt-12 mb-3 scroll-mt-24 text-balance text-xl font-semibold tracking-tight text-foreground sm:text-2xl\">Conclusion</h2>\n<p class=\"mb-5 text-[15px] leading-7 text-foreground/75 sm:text-base sm:leading-[1.75]\">If you&#x27;re building a React application today, Next.js is the way to go. It provides a robust framework that handles the heavy lifting, letting you focus on building features.</p>"
};
